package net.imadz.codegen.scaffolding.cqrs.template.products

import net.imadz.codegen.scaffolding.cqrs.TypeResolverDSL
import net.imadz.codegen.scaffolding.cqrs.model.products._
import net.imadz.codegen.structure.NamingConventions
import net.imadz.meta.execution._
import net.imadz.meta.products._

object ProductApplicationTemplate {
  private def sym(value: String): String = NamingConventions.productSymbol(value)
  private def quote(value: String): String = ujson.write(value)
  private def typeText(ref: net.imadz.codegen.scaffolding.cqrs.TypeRef): String = ref.fqn + (if (ref.typeParams.isEmpty) "" else ref.typeParams.map(typeText).mkString("[", ", ", "]"))
  private def tpe(value: NominalType, model: ProductApplicationModel): String = typeText(TypeResolverDSL.productType(value, model.domain.packages))
  private def field(r: QualifiedReference, model: ProductApplicationModel): ReferenceDeclaration = model.domain.layout.declarations.find(_.ref == r).get
  private def raw(value: String, t: NominalType, model: ProductApplicationModel): String = t match { case NominalType.Named(r) => raw(value + ".value", field(r, model).valueType.get, model); case _ => value }
  private def stem(h: SagaHostContract): String = NamingConventions.strictSymbol(h.id)
  private def method(p: HostParticipant, phase: HostPhase): String = NamingConventions.strictSymbol(p.stepId + "_" + phase.phase.wire)
  private def source(path: String, text: String, kind: String, h: SagaHostContract, model: ProductApplicationModel): ProductSourceModel =
    ProductSourceModel(path, "// @generated by CodegenMain:semantic-products-application-1\n" + text, kind, Vector(h.source), model.footprint)

  private def fromTechnical(h: SagaHostContract, name: String, model: ProductApplicationModel): String = {
    def identity(key: SagaIdentityPart): String = key match {
      case SagaIdentityPart.Transaction => "request.identity.transaction.transactionId"
      case SagaIdentityPart.DefinitionVersion => "request.identity.transaction.definitionVersion.toString"
      case SagaIdentityPart.ArgsDigest => "request.identity.transaction.argsDigest"
      case SagaIdentityPart.Participant => "request.identity.participantId"
      case SagaIdentityPart.Resource => "request.identity.resource"
      case SagaIdentityPart.Step => "request.identity.stepId"
      case SagaIdentityPart.Phase => "request.identity.phase.toString.toLowerCase(java.util.Locale.ROOT)"
    }
    var text = "  def fromTechnical(objects: " + name + "TechnicalPorts.Installed)(implicit ec: ExecutionContext): Ports = {\n    require(objects != null, \"installed technical objects required\")\n    new Ports {\n      val technical = objects\n      val installed = objects.declarations\n"
    h.participants.foreach { p => p.phases.foreach { pf =>
      val m = method(p, pf); val receipt = tpe(pf.evidence.receiptType, model)
      val members = field(pf.query.inputType.asInstanceOf[NominalType.Named].ref, model).valueType.get.asInstanceOf[NominalType.Record].members
      val queryValues = members.map { member =>
        val mapping = pf.evidence.identity.find(_.member.id == member.id).get
        val value = identity(mapping.key)
        field(member, model).valueType.get match { case n: NominalType.Named => tpe(n, model) + "(" + value + ")"; case _ => value }
      }
      val inputs = pf.parameters.map(m => "command" + method(p, pf) + "(request)." + sym(m.parameter.id))
      text += "      val " + m + ": PhasePort[Args, " + receipt + "] = new PhasePort[Args, " + receipt + "] {\n        val receiptCodec = " + m + "Codec\n        val querySafety = QuerySafety.DeclaredReadOnly\n"
      text += "        def execute(request: OperationRequest[Args]): Future[PhaseOutcome[" + receipt + "]] = objects." + NamingConventions.strictSymbol(pf.executePort.ref.id) + "Operation(" + tpe(pf.inputType, model) + "(" + inputs.mkString(", ") + "), request.identity).map[PhaseOutcome[" + receipt + "]](r => ConfirmedReceipt(request.identity, r)).recover { case ex: " + name + "TechnicalPorts.OperationNotExecuted if ex.identity == request.identity && ex.evidence != null && ex.evidence.nonEmpty => NotExecuted(request.identity, ex.evidence, ex.safeToRetry); case ex => Unknown(request.identity, \"technical execute failed: \" + ex.getMessage) }\n"
      text += "        def query(request: OperationRequest[Args]): Future[PhaseOutcome[" + receipt + "]] = objects." + NamingConventions.strictSymbol(pf.query.port.ref.id) + "Operation(" + tpe(pf.query.inputType, model) + "(" + queryValues.mkString(", ") + "), request.identity).map { case Some(r) => ConfirmedReceipt(request.identity, r); case None => Unknown(request.identity, \"typed query returned no authoritative evidence\") }.recover { case ex: " + name + "TechnicalPorts.OperationNotExecuted if ex.identity == request.identity && ex.evidence != null && ex.evidence.nonEmpty => NotExecuted(request.identity, ex.evidence, ex.safeToRetry); case ex => Unknown(request.identity, \"technical query failed: \" + ex.getMessage) }\n      }\n"
    } }
    text + "    }\n  }\n"
  }

  def generate(model: ProductApplicationModel): Vector[ProductSourceModel] = model.hosts.flatMap { row =>
    val h = row.contract; val runtime = row.runtime; val pkg = model.domain.packages(h.saga.ref.context); val name = stem(h)
    val args = tpe(h.argsType, model); val converters = pkg + ".infrastructure.serialization.DomainConverters"; val pb = pkg + ".infrastructure.proto."
    def codecMethod(p: HostParticipant, phase: HostPhase): String = method(p, phase) + "Codec"
    def parameter(m: HostParameter): String = m.input match {
      case SagaValueSource.TransactionId => field(m.parameter, model).valueType.get match {
        case n: NominalType.Named => tpe(n, model) + "(request.identity.transaction.transactionId)"
        case _ => "request.identity.transaction.transactionId"
      }
      case SagaValueSource.Args(slot) => "request.args." + sym(slot)
      case SagaValueSource.StepReceipt(step, phase, slot) =>
        val producer = h.participants.find(_.stepId == step).get; val pf = producer.phases.find(_.phase == phase).get
        val member = pf.evidence.payload.find(_.output == slot).get.member
        val rp = runtime.participants.find(_.stepId == step).get
        "request.receipt(request.identity.copy(participantId = " + quote(producer.participantId) + ", resource = " + raw("request.args." + sym(rp.resource.source.slot), field(producer.resourceInput, model).valueType.get, model) + ", stepId = " + quote(step) + ", phase = Phase." + phase.runtimeName + "), " + codecMethod(producer, pf) + ".pin, " + codecMethod(producer, pf) + ").get." + sym(member.id)
      case _ => throw new IllegalArgumentException("unsupported application phase input")
    }
    var text = "package " + pkg + ".application\n\nimport akka.actor.typed.Behavior\nimport akka.persistence.typed.PersistenceId\nimport com.google.protobuf.ByteString\nimport net.imadz.infra.saga.strict._\nimport scala.concurrent.{ExecutionContext, Future}\nimport scala.util.Try\n\nobject " + name + "Definition {\n  type Args = " + args + "\n"
    text += "  val argsCodec: PayloadCodec[Args] = new PayloadCodec[Args] {\n    val pin = CodecPin(" + quote(runtime.args.codecs.runtimeCodec.id) + ", " + runtime.args.codecs.runtimeCodec.version + ")\n    def encode(value: Args): ByteString = " + converters + ".encode" + h.argsType.asInstanceOf[NominalType.Named].ref.id + "PB(value).toByteString\n    def decode(bytes: ByteString): Try[Args] = Try(" + converters + ".decode" + h.argsType.asInstanceOf[NominalType.Named].ref.id + "PB(" + pb + h.argsType.asInstanceOf[NominalType.Named].ref.id + "PB.parseFrom(bytes.toByteArray)))\n  }\n"
    text += "  trait Ports {\n    def technical: " + name + "TechnicalPorts.Installed\n    def installed: Map[String, (String, String)]\n" + h.participants.flatMap(p => p.phases.map(pf => "    def " + method(p, pf) + ": PhasePort[Args, " + tpe(pf.evidence.receiptType, model) + "]\n")).mkString + "  }\n"
    text += fromTechnical(h, name, model)
    h.participants.foreach { p => p.phases.foreach { pf =>
      val m = method(p, pf); val receipt = tpe(pf.evidence.receiptType, model); val receiptName = pf.evidence.receiptType.asInstanceOf[NominalType.Named].ref.id
      text += "  val " + m + "Codec: PayloadCodec[" + receipt + "] = new PayloadCodec[" + receipt + "] {\n    val pin = CodecPin(" + quote(pf.evidence.codec.runtimeCodec.id) + ", " + pf.evidence.codec.runtimeCodec.version + ")\n    def encode(value: " + receipt + "): ByteString = " + converters + ".encode" + receiptName + "PB(value).toByteString\n    def decode(bytes: ByteString): Try[" + receipt + "] = Try(" + converters + ".decode" + receiptName + "PB(" + pb + receiptName + "PB.parseFrom(bytes.toByteArray)))\n  }\n"
      text += "  def check" + m + "(request: OperationRequest[Args], receipt: " + receipt + "): Unit = {\n"
      pf.evidence.identity.foreach { member =>
        val expected = member.key match {
          case SagaIdentityPart.Transaction => "request.identity.transaction.transactionId"
          case SagaIdentityPart.DefinitionVersion => "request.identity.transaction.definitionVersion.toString"
          case SagaIdentityPart.ArgsDigest => "request.identity.transaction.argsDigest"
          case SagaIdentityPart.Participant => "request.identity.participantId"
          case SagaIdentityPart.Resource => "request.identity.resource"
          case SagaIdentityPart.Step => "request.identity.stepId"
          case SagaIdentityPart.Phase => "request.identity.phase.toString.toLowerCase(java.util.Locale.ROOT)"
        }
        text += "    require(" + raw("receipt." + sym(member.member.id), field(member.member, model).valueType.get, model) + " == " + expected + ", " + quote("receipt " + member.key.wire + " differs from durable operation") + ")\n"
      }
      text += "  }\n  def command" + m + "(request: OperationRequest[Args]): " + pkg + ".domain." + sym(p.aggregate.id) + "Protocol." + sym(pf.command.id) + " = " + pkg + ".domain." + sym(p.aggregate.id) + "Protocol." + sym(pf.command.id) + pf.parameters.map(parameter).mkString("(", ", ", ")\n")
      text += "  private def bind" + m + "(underlying: PhasePort[Args, " + receipt + "])(implicit ec: ExecutionContext): PhaseBinding[Args] = {\n    require(underlying != null && underlying.receiptCodec != null && underlying.receiptCodec.pin == " + m + "Codec.pin && underlying.querySafety == QuerySafety.DeclaredReadOnly, \"required read-only phase port and exact codec implementation\")\n    val checked = new PhasePort[Args, " + receipt + "] {\n      val receiptCodec = " + m + "Codec\n      val querySafety = QuerySafety.DeclaredReadOnly\n      private def validate(result: Future[PhaseOutcome[" + receipt + "]], request: OperationRequest[Args]): Future[PhaseOutcome[" + receipt + "]] = result.map {\n        case c @ ConfirmedReceipt(identity, receipt) => require(identity == request.identity, \"operation identity mismatch\"); check" + m + "(request, receipt); c\n        case other => require(other.identity == request.identity, \"operation identity mismatch\"); other\n      }\n      def execute(request: OperationRequest[Args]): Future[PhaseOutcome[" + receipt + "]] = validate(underlying.execute(request), request)\n      def query(request: OperationRequest[Args]): Future[PhaseOutcome[" + receipt + "]] = validate(underlying.query(request), request)\n    }\n    PhaseBinding(checked)\n  }\n"
    } }
    text += "  def definition(ports: Ports)(implicit ec: ExecutionContext): StrictSagaDefinition[Args] = {\n    require(ports != null && ports.technical != null, \"all required implementation objects must be injected\")\n    require(ports.installed == ports.technical.declarations, \"installation declarations must come from exact typed objects\")\n    " + name + "TechnicalPorts.requireInstalled(ports.installed)\n"
    h.participants.foreach(p => p.phases.foreach(pf => text += "    val installed_" + method(p, pf) + " = bind" + method(p, pf) + "(ports." + method(p, pf) + ")\n"))
    text += "    StrictSagaDefinition(" + quote(runtime.runtimeIdentity.name) + ", " + runtime.runtimeIdentity.version + ", " + quote(runtime.definitionDigest) + ", argsCodec, args => Vector(\n" + h.participants.map { p =>
      val rp = runtime.participants.find(_.stepId == p.stepId).get
      "      StrictParticipant[Args](" + quote(p.stepId) + ", " + quote(p.participantId) + ", " + raw("args." + sym(rp.resource.source.slot), field(p.resourceInput, model).valueType.get, model) + ", Map(" + p.phases.map(pf => "Phase." + pf.phase.runtimeName + " -> installed_" + method(p, pf)).mkString(", ") + "))"
    }.mkString(",\n") + "\n    ))\n  }\n  def coordinator(persistenceId: String, ports: Ports, authorizer: ReconcileAuthorizer)(implicit ec: ExecutionContext): Behavior[StrictSagaCoordinator.Command] = {\n    require(persistenceId != null && persistenceId.nonEmpty && authorizer != null, \"explicit identity and reconciliation authorizer required\")\n    StrictSagaCoordinator(PersistenceId.ofUniqueId(persistenceId), definition(ports), authorizer, StrictSagaCoordinator.Settings(scala.concurrent.duration.Duration(" + runtime.coordinator.interactionTimeoutMs + ", \"millis\"), 32))\n  }\n}\n"
    Vector(source(NamingConventions.productPackagePath(pkg, "application/" + name + "Definition.scala"), text, "saga-definition", h, model))
  }
}
